import {MOTION} from '../data/offers.js';
import {icon} from './icons.js';
export class Motion {
 constructor(getSettings){this.settings=getSettings;this.reduced=matchMedia('(prefers-reduced-motion: reduce)');this.low=(navigator.hardwareConcurrency||8)<=4||(navigator.deviceMemory||8)<=4;this.counters=new Map();this.active=new Set();this.particles=0;this.frame=0;this.attach();document.addEventListener('visibilitychange',()=>{if(document.hidden)this.cancel();});}
 get enabled(){return !this.reduced.matches&&this.settings()?.motion!==false&&!document.hidden;}
 get rich(){return this.enabled&&this.settings()?.effects!==false;}
 animate(el,frames,options){if(!el||!this.enabled)return null;const a=el.animate(frames,{duration:210,easing:'cubic-bezier(.2,.8,.25,1)',...options});this.active.add(a);a.finished.catch(()=>{}).finally(()=>this.active.delete(a));return a;}
 attach(){let pressed=null;document.addEventListener('pointerdown',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;pressed=b;this.animate(b,[{transform:'scale(1)'},{transform:'scale(.955)'}],{duration:MOTION.pressMs,fill:'forwards'});});const release=()=>{if(!pressed)return;pressed.getAnimations().forEach(a=>a.cancel());this.animate(pressed,[{transform:'scale(.955)'},{transform:'scale(1.025)',offset:.6},{transform:'scale(1)'}],{duration:MOTION.releaseMs});pressed=null;};document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const {action,id}=b.dataset;queueMicrotask(()=>{if(!b.isConnected&&action){const replacement=[...document.querySelectorAll('[data-action]')].find(n=>n.dataset.action===action&&n.dataset.id===id);this.animate(replacement,[{transform:'scale(.96)'},{transform:'scale(1.025)'},{transform:'scale(1)'}],{duration:MOTION.releaseMs});}});});document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('button'))this.animate(e.target,[{transform:'scale(.96)'},{transform:'scale(1)'}],{duration:160});});}
 counter(el,key,value,format){if(!el)return;const old=this.counters.get(key);if(!this.enabled||!old){el.textContent=format(value);this.counters.set(key,{value,target:value,el,format,start:0});return;}if(old.target===value&&old.el===el)return;this.counters.set(key,{from:old.value,value:old.value,target:value,start:performance.now(),el,format});this.schedule();}
 schedule(){if(this.frame)return;this.frame=requestAnimationFrame(now=>{this.frame=0;let busy=false;for(const c of this.counters.values()){if(c.value===c.target)continue;const p=Math.min(1,(now-c.start)/MOTION.counterMs),ease=1-(1-p)**3;c.value=c.from+(c.target-c.from)*ease;if(c.el?.isConnected)c.el.textContent=c.format(c.value);if(p===1)c.value=c.target;else busy=true;}if(busy)this.schedule();});}
 enter(){document.querySelectorAll('.job-card,.shop-card,.skill-card,.rank-row,.goal-card,.collection-card').forEach((el,i)=>{if(i<10)this.animate(el,[{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:MOTION.cardMs,delay:Math.min(i*18,90)});});}
 pulse(el){this.animate(el,[{transform:'scale(1)'},{transform:'scale(1.065)'},{transform:'scale(1)'}],{duration:240});}
 xp(){const el=document.querySelector('.xp-track');this.animate(el,[{boxShadow:'0 0 0 0 #a9d77700'},{boxShadow:'0 0 0 5px #a9d77760'},{boxShadow:'0 0 0 0 #a9d77700'}],{duration:400});}
 coins(origin){if(!this.rich)return;const to=document.querySelector('.money-value')?.getBoundingClientRect();if(!to)return;const from=origin||document.querySelector('.collection-card')?.getBoundingClientRect()||to;const cap=this.low?MOTION.lowParticles:MOTION.maxParticles,n=Math.min(this.low?4:7,cap-this.particles);for(let i=0;i<n;i++){const node=document.createElement('span');node.className='fx-coin';node.innerHTML=icon('coin');document.body.append(node);this.particles++;const x=from.x+from.width/2,y=from.y+from.height/2,tx=to.x+to.width/2-x,ty=to.y+to.height/2-y;node.style.left=x+'px';node.style.top=y+'px';const a=this.animate(node,[{transform:'translate(-50%,-50%) scale(.65)',opacity:0},{transform:`translate(${(i-n/2)*12}px,-36px) scale(1)`,opacity:1,offset:.25},{transform:`translate(${tx}px,${ty}px) scale(.5)`,opacity:0}],{duration:MOTION.coinMs,delay:i*35,easing:'cubic-bezier(.25,.05,.55,1)'});if(a)a.finished.catch(()=>{}).finally(()=>{node.remove();this.particles--;});else{node.remove();this.particles--;}}setTimeout(()=>this.pulse(document.querySelector('.money-value')),MOTION.coinMs);}
 burst(el){if(!this.rich||!el)return;const r=el.getBoundingClientRect(),count=Math.min(this.low?4:9,(this.low?MOTION.lowParticles:MOTION.maxParticles)-this.particles);for(let i=0;i<count;i++){const node=document.createElement('i');node.className='fx-particle';node.style.cssText=`left:${r.x+r.width/2}px;top:${r.y+r.height/2}px;background:${['#95bb69','#e0bb66','#8eaeb1'][i%3]}`;document.body.append(node);this.particles++;const angle=i/count*Math.PI*2,a=this.animate(node,[{transform:'translate(0,0) scale(0)',opacity:0},{opacity:1,offset:.15},{transform:`translate(${Math.cos(angle)*64}px,${Math.sin(angle)*48}px) rotate(120deg) scale(.4)`,opacity:0}],{duration:550});a?.finished.catch(()=>{}).finally(()=>{node.remove();this.particles--;});}}
 celebrate(title,detail,kind='spark'){const node=document.createElement('div');node.className='reward-sequence';node.innerHTML=`<span>${icon(kind)}</span><div><strong></strong><small></small></div>`;node.querySelector('strong').textContent=title;node.querySelector('small').textContent=detail;document.body.append(node);this.animate(node,[{transform:'translate(-50%,-10px) scale(.92)',opacity:0},{transform:'translate(-50%,0) scale(1.035)',opacity:1,offset:.22},{transform:'translate(-50%,0) scale(1)',opacity:1,offset:.8},{transform:'translate(-50%,-8px) scale(.98)',opacity:0}],{duration:MOTION.rewardMs});this.burst(document.querySelector('.avatar'));setTimeout(()=>node.remove(),this.enabled?MOTION.rewardMs:1100);}
 shake(){if(this.low||!this.rich)return;this.animate(document.querySelector('#screen'),[{transform:'translateX(0)'},{transform:'translateX(-2px)'},{transform:'translateX(2px)'},{transform:'translateX(-1px)'},{transform:'translateX(0)'}],{duration:180});}
 room(oldRoom){const current=document.querySelector('.room');if(!current)return;this.animate(current,[{opacity:.35,transform:'scale(.98)'},{opacity:1,transform:'scale(1)'}],{duration:MOTION.roomMs});this.burst(current);if(oldRoom&&this.enabled){const overlay=oldRoom.cloneNode(true);overlay.classList.add('room-outgoing');overlay.setAttribute('aria-hidden','true');current.append(overlay);const a=this.animate(overlay,[{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(1.04)'}],{duration:MOTION.roomMs});a?.finished.catch(()=>{}).finally(()=>overlay.remove());}}
 cancel(){this.active.forEach(a=>a.cancel());this.active.clear();if(this.frame)cancelAnimationFrame(this.frame);this.frame=0;for(const c of this.counters.values()){c.value=c.target;if(c.el?.isConnected)c.el.textContent=c.format(c.target);}}
}
